package com.juner2026.crabpet;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.net.Uri;import android.provider.Settings;import android.widget.*;
public class MainActivity extends Activity{ public void onCreate(Bundle b){super.onCreate(b); LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(40,50,40,40); TextView t=new TextView(this);t.setText("AI小螃蟹\n\n授权悬浮窗后，桌宠会出现在屏幕上。\n\n单击改变表情。双击开心。长按隐藏。拖动移动。");t.setTextSize(20);t.setTextColor(Color.rgb(90,65,70));l.addView(t);Button p=new Button(this);p.setText("授权悬浮窗并启动");p.setOnClickListener(v->{if(!Settings.canDrawOverlays(this))startActivity(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION, Uri.parse("package:"+getPackageName())));else startService(new Intent(this,PetService.class));});l.addView(p);setContentView(l);}}